 "content": "def transform(grid):
    """Magnify: each colored cell is replaced by the complement of the input mask."""
    h, w = len(grid), len(grid[0])
    motif = [[not bool(grid[r][c]) for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(w * h)] for _ in range(h * h)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
